export const generatePriceHistory = (basePrice, days = 90) => {
  const data = []
  const now = new Date()
  for (let i = days; i >= 0; i--) {
    const date = new Date(now)
    date.setDate(date.getDate() - i)
    data.push({
      date: date.toISOString().split('T')[0],
      amazon: Math.round(basePrice * (0.9 + Math.random() * 0.2)),
      flipkart: Math.round(basePrice * (0.88 + Math.random() * 0.22)),
      lowest: Math.round(basePrice * (0.85 + Math.random() * 0.3)),
    })
  }
  return data
}

export const formatUSD = (usdPrice) => {
  if (usdPrice == null) return '';
  const num = Number(usdPrice);
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: num % 1 === 0 ? 0 : 2
  }).format(num);
}

export const formatINR = (inrPrice) => {
  if (inrPrice == null) return '';
  const num = Number(inrPrice);
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: num % 1 === 0 ? 0 : 2
  }).format(num);
}

export const formatPrice = (amount, currency = 'INR', options = {}) => {
  if (amount == null) return '';
  const num = Number(amount);
  if (isNaN(num)) return '';

  let curr = (typeof currency === 'string' ? currency : (currency && currency.currency) || 'INR').toUpperCase();

  if (curr === 'USD') {
    return formatUSD(num);
  }

  // Default is canonical Indian marketplace INR
  const inrFormatted = formatINR(num);
  if (options && options.showUSD) {
    const usdEquiv = Math.round((num / 84) * 100) / 100;
    return `${inrFormatted} (${formatUSD(usdEquiv)})`;
  }
  return inrFormatted;
}
